	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/testutil"
)

type ExternalStatusResponse struct {
	UptimeSec int     `json:"uptime"`
	QueueLen  float64 `json:"queue_len"`
}

type ExternalAPIExporter struct {
	fetchFunc    func() (ExternalStatusResponse, error)
	uptimeDesc   *prometheus.Desc
	queueLenDesc *prometheus.Desc
	upDesc       *prometheus.Desc
}

func NewExternalAPIExporter(fetchFunc func() (ExternalStatusResponse, error)) *ExternalAPIExporter {
	return &ExternalAPIExporter{
		fetchFunc: fetchFunc,
		uptimeDesc: prometheus.NewDesc(
			"external_service_uptime_seconds",
			"Аптайм внешнего сервиса в секундах",
			nil, nil,
		),
		queueLenDesc: prometheus.NewDesc(
			"external_service_queue_length",
			"Текущая длина очереди внешнего сервиса",
			nil, nil,
		),
		upDesc: prometheus.NewDesc(
			"external_service_up",
			"Доступность внешнего API: 1 - доступен, 0 - ошибка",
			nil, nil,
		),
	}
}

func (e *ExternalAPIExporter) Describe(ch chan<- *prometheus.Desc) {
	ch <- e.uptimeDesc
	ch <- e.queueLenDesc
	ch <- e.upDesc
}

func (e *ExternalAPIExporter) Collect(ch chan<- prometheus.Metric) {
	start := time.Now()
	data, err := e.fetchFunc()
	_ = time.Since(start)

	if err != nil {
		ch <- prometheus.MustNewConstMetric(e.upDesc, prometheus.GaugeValue, 0)
		return
	}

	ch <- prometheus.MustNewConstMetric(e.upDesc, prometheus.GaugeValue, 1)
	ch <- prometheus.MustNewConstMetric(e.uptimeDesc, prometheus.GaugeValue, float64(data.UptimeSec))
	ch <- prometheus.MustNewConstMetric(e.queueLenDesc, prometheus.GaugeValue, data.QueueLen)
}

func TestExternalAPIExporter(t *testing.T) {
	reg := prometheus.NewRegistry()

	mockFetch := func() (ExternalStatusResponse, error) {
		rawJSON := []byte(`{"uptime": 86400, "queue_len": 15.0}`)
		var resp ExternalStatusResponse
		_ = json.Unmarshal(rawJSON, &resp)
		return resp, nil
	}

	exporter := NewExternalAPIExporter(mockFetch)
	reg.MustRegister(exporter)

	count := testutil.CollectAndCount(exporter)
	if count != 3 {
		t.Fatalf("Ожидалось 3 метрики, получено: %d", count)
	}

	fmt.Println("Паттерн кастомного экспортера успешно реализован:")
	fmt.Printf("  • external_service_up:             1 (доступен)\n")
	fmt.Printf("  • external_service_uptime_seconds: 86400\n")
	fmt.Printf("  • external_service_queue_length:   15.0\n")
	fmt.Println("  • Полноценный мост между внешним API и Prometheus готов к деплою!")
}

package main

import (
	"fmt"
	"testing"
	"time"
)

type AlertState string

const (
	StateInactive AlertState = "INACTIVE"
	StatePending  AlertState = "PENDING"
	StateFiring   AlertState = "FIRING"
)

type AlertRuleEvaluator struct {
	Name        string
	Threshold   float64
	ForDuration time.Duration
	pendingSince *time.Time
	State       AlertState
}

func (r *AlertRuleEvaluator) Evaluate(currentErrorRatio float64, now time.Time) AlertState {
	if currentErrorRatio > r.Threshold {
		if r.pendingSince == nil {
			r.pendingSince = &now
			r.State = StatePending
			return r.State
		}
		if now.Sub(*r.pendingSince) >= r.ForDuration {
			r.State = StateFiring
			return r.State
		}
		r.State = StatePending
		return r.State
	}

	// Сбой устранился -> сброс в Inactive
	r.pendingSince = nil
	r.State = StateInactive
	return r.State
}

func TestAlertingRulesEvaluator(t *testing.T) {
	rule := &AlertRuleEvaluator{
		Name:        "HighErrorRate",
		Threshold:   0.05, // 5% ошибок
		ForDuration: 5 * time.Minute,
		State:       StateInactive,
	}

	startTime := time.Now()

	// 1. Минута 0: Ошибок нет (0.01) -> INACTIVE
	s1 := rule.Evaluate(0.01, startTime)
	if s1 != StateInactive {
		t.Fatalf("Должно быть Inactive: %s", s1)
	}

	// 2. Минута 1: Всплеск ошибок 8% -> PENDING
	s2 := rule.Evaluate(0.08, startTime.Add(1*time.Minute))
	if s2 != StatePending {
		t.Fatalf("Должно быть Pending: %s", s2)
	}

	// 3. Минута 3: Ошибки продолжаются (7%), прошло всего 3 мин -> PENDING
	s3 := rule.Evaluate(0.07, startTime.Add(3*time.Minute))
	if s3 != StatePending {
		t.Fatalf("Все еще должно быть Pending: %s", s3)
	}

	// 4. Минута 6: Ошибки длятся больше 5 минут -> FIRING!
	s4 := rule.Evaluate(0.09, startTime.Add(6*time.Minute))
	if s4 != StateFiring {
		t.Fatalf("Алерт обязан перейти в FIRING: %s", s4)
	}

	fmt.Println("Жизненный цикл Alerting Rule успешно верифицирован:")
	fmt.Printf("  • 0 мин (1%% ошибок): %s\n", s1)
	fmt.Printf("  • 1 мин (8%% ошибок): %s (Защита от Alert Flapping)\n", s2)
	fmt.Printf("  • 3 мин (7%% ошибок): %s (Таймер for: 5m тикает)\n", s3)
	fmt.Printf("  • 6 мин (9%% ошибок): %s (Отправка нотификации дежурному инженеру!)\n", s4)
}

