type AlertPayload struct {
	Status string `json:"status"`
	Alerts []struct {
		Labels map[string]string `json:"labels"`
	} `json:"alerts"`
}

func TestWebhookAlertReceiver(t *testing.T) {
	var receivedAlert string

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var p AlertPayload
		_ = json.NewDecoder(r.Body).Decode(&p)
		if len(p.Alerts) > 0 {
			receivedAlert = p.Alerts[0].Labels["alertname"]
		}
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	// Имитируем отправку вебхука из Alertmanager
	payload := `{
		"status": "firing",
		"alerts": [
			{"labels": {"alertname": "High5xxErrorRate", "severity": "critical"}}
		]
	}`

	resp, err := http.Post(server.URL, "application/json", strings.NewReader(payload))
	if err != nil || resp.StatusCode != http.StatusOK {
		t.Fatalf("Ошибка отправки вебхука: %v", err)
	}

	if receivedAlert != "High5xxErrorRate" {
		t.Fatalf("Ожидался алерт High5xxErrorRate, получено: %s", receivedAlert)
	}

	fmt.Println("Вебхук нотификаций Prometheus Alertmanager успешно проверен:")
	fmt.Printf("  • HTTP POST:  %s\n", server.URL)
	fmt.Printf("  • Алерт:      %s (firing)\n", receivedAlert)
